    // Ask user how many numbers to input
    let count = parseInt(prompt("How many numbers do you want to enter?"));

    // Create an empty array to store numbers
    let numArray = [];

    // Loop to input numbers one by one
    for (let i = 0; i < count; i++) {
        let num = parseFloat(prompt(`Enter number ${i+1}:`));
        numArray.push(num);
    }

    // Check if array has at least one number
    if (numArray.length > 0) {
        // Find max and min values
        let maxVal = Math.max(...numArray);
        let minVal = Math.min(...numArray);

        // Print max and min values
        console.log(`Maximum value: ${maxVal}`);
        console.log(`Minimum value: ${minVal}`);
    } else {
        console.log("No numbers entered.");
    }
}

// Call the function
findMaxMin();
```

